## Code Example
```javascript
// Pseudo: envelope encrypt data per tenant
function encryptForTenant(tenantId, plaintext, version) {
  const keyId = kms.getKeyId(tenantId, version);
  const dataKey = kms.generateDataKey(tenantId, version);
  const ciphertext = crypto.aesGcmEncrypt(dataKey.plaintext, plaintext);
  const envelope = { keyId, cipher: ciphertext, iv: dataKey.iv };
  return envelope;
}
```

